-- Table and column names are exactly the ones given in the README (camelCase). Postgres folds unquoted
-- names to lower case, so they are quoted here; JPA quotes them too (hibernate.globally_quoted_identifiers).

CREATE TABLE "timeDeposits"
(
    "id"       INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Assumption: plan types are short codes such as 'basic'; any value is allowed, unknown plans earn no interest.
    "planType" VARCHAR(50)    NOT NULL,
    "days"     INTEGER        NOT NULL,
    -- Assumption: money is stored in cents precision (2 decimals); the README only says "Decimal".
    -- At most 15 digits (balances below 10^13): the legacy TimeDeposit holds the balance as a double, which keeps
    -- 15 significant digits exactly, so every stored balance converts to a double and back unchanged.
    "balance"  NUMERIC(15, 2) NOT NULL
);

CREATE TABLE "withdrawals"
(
    "id"            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "timeDepositId" INTEGER        NOT NULL REFERENCES "timeDeposits" ("id"),
    -- Same precision as the balance.
    "amount"        NUMERIC(15, 2) NOT NULL,
    "date"          DATE           NOT NULL
);

-- Postgres does not index foreign keys by itself; withdrawals are read per time deposit.
CREATE INDEX "withdrawals_timeDepositId_idx" ON "withdrawals" ("timeDepositId");
